from panda_backtest.api.stock_api import *
import numpy as np
import pandas as pd
import datetime

W = {'510300.SH': 0.40, '511260.SH': 0.40, '518880.SH': 0.20}

def initialize(context):
    context.hist = {s: [] for s in W}
    context.prev_month = None

