    context.hist = {s: [] for s in EQ + [BOND]}
    context.prev_month = None

def handle_data(context, bar):
    acc = context.stock_account_dict['8888']
    try:
        dt = datetime.datetime.strptime(str(context.trade_date), '%Y%m%d')
